        return 0.0

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, 63.0))
        return float(min(budget, 28.0))

    prev_bids = []
    threat_bids = []
    cindy_bid = None
    for opp in alive_opponents:
